#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace fedspatial; namespace fs=std::filesystem;
static constexpr double kReferenceSymmetryTolerance=1e-10;
static Matrix load(const fs::path&p){std::ifstream f(p);int r,c;if(!(f>>r>>c))throw std::runtime_error("missing "+p.string());Matrix x(r,c);for(double&v:x.a)f>>v;return x;}
static WorkerInput worker100(int n){auto a=load("sync_gpu/tests/fixtures/figure1_reference/worker_0.txt");Matrix s(n,2),z(n,1),x(n,5);for(int i=0;i<n;++i){s(i,0)=a(i,0);s(i,1)=a(i,1);z(i,0)=a(i,2);for(int j=0;j<5;++j)x(i,j)=a(i,j+3);}return{s,z,x};}
static double dot(const Matrix&a,const Matrix&b){double x=0.;for(size_t i=0;i<a.a.size();++i)x+=a.a[i]*b.a[i];return x;}
static double tr(const Matrix&a){double x=0.;for(int i=0;i<a.rows;++i)x+=a(i,i);return x;}
static double symerr(const Matrix&h){return std::max(std::abs(h(0,1)-h(1,0)),std::abs(h(0,2)-h(2,0)));}
static bool run_small(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sig(2,2);double av[]={0,0,1,.2,.3,1.1},kv[]={0,0,1.5,1.5},zv[]={1.2,-.4,.7};std::copy(av,av+6,s.a.begin());std::copy(kv,kv+4,k.a.begin());std::copy(zv,zv+3,z.a.begin());for(double&v:x.a)v=1.;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sig(0,0)=.7;sig(1,1)=.4;sig(0,1)=sig(1,0)=.05;const auto point=load("sync_gpu/tests/fixtures/sync_gpu/DELTA_THETA_POINT0_PARAM.txt");const auto want=load("sync_gpu/tests/fixtures/sync_gpu/DELTA_THETA_POINT0_HESSIAN.txt");GlobalParameters p{g,mu,sig,point(0,0),point(1,0),point(2,0)};WorkerInput w{s,z,x};GpuContext c(0);(void)build_device_mu_sigma_local(c,w,k,p);auto h0=c.raw_h2d_bytes(),d0=c.result_d2h_bytes();auto a=compute_device_delta_theta_mixed_hessian_reduction_streamed(c,w,k,p);auto h1=c.raw_h2d_bytes(),d1=c.result_d2h_bytes();auto b=compute_device_delta_theta_mixed_hessian_reduction_streamed(c,w,k,p);GpuContext dc(0);auto state=build_device_mu_sigma_local(dc,w,k,p);auto local=download_device_mu_sigma_local(dc,state);auto fixed=download_device_delta_theta_workspace_for_test(dc,build_device_delta_theta_workspace(dc,state));auto deriv=download_device_delta_theta_derivative_workspace_for_test(dc,build_device_delta_theta_derivative_workspace(dc,state));auto md=download_device_m_derivatives(dc,compute_device_m_derivatives(dc,p.nu2,p.delta,p.alpha,p.range)).first;double termerr=0.;for(int q=0;q<2;++q){const int i=q+1;const Matrix&T=(i==1?md.alpha:md.range);const Matrix W2=matmul(fixed.W,fixed.W),wu=matmul(fixed.W,fixed.u),tu=matmul(T,fixed.u),wtu=matmul(fixed.W,tu),rt=matmul(deriv.B_i[i],p.mu);const Matrix wt=matmul(fixed.W,T);std::array<double,5> ref={tr(matmul(wt,fixed.W))/p.delta,2.*dot(rt,wu),-2.*dot(fixed.u,wtu),2.*tr(matmul(matmul(matmul(deriv.B_i[i],p.sigma),transpose(local.B)),W2)),-2.*tr(matmul(matmul(matmul(matmul(local.B,p.sigma),transpose(local.B)),fixed.W),matmul(T,W2)))};for(int t=0;t<5;++t)termerr=std::max(termerr,std::abs(a.terms[q][t]-ref[t]));std::cout<<"STREAM_MIXED_HESSIAN_N=3 "<<(q?"RANGE":"ALPHA")<<" TERM0="<<std::abs(a.terms[q][0]-ref[0])<<" TERM1="<<std::abs(a.terms[q][1]-ref[1])<<" TERM2="<<std::abs(a.terms[q][2]-ref[2])<<" TERM3="<<std::abs(a.terms[q][3]-ref[3])<<" TERM4="<<std::abs(a.terms[q][4]-ref[4])<<" PYTHON_AUTOGRAD_ABS="<<std::abs(a.mixed[q]-want(0,i))<<'\n';}double err=std::max(std::abs(a.mixed[0]-want(0,1)),std::abs(a.mixed[1]-want(0,2))),se=symerr(want);bool repeat=std::memcmp(&a,&b,sizeof(a))==0,zero=c.raw_h2d_bytes()==h1,sym=se<=kReferenceSymmetryTolerance;std::cout<<"STREAM_MIXED_HESSIAN_SMALL PYTHON_AUTOGRAD_MAX_ABS="<<err<<" TERM_MAX_ABS="<<termerr<<" SYMMETRY_MAX_ABS="<<se<<" SYMMETRY="<<(sym?"PASS":"FAIL")<<" EXACT_REPEAT="<<(repeat?"PASS":"FAIL")<<" ACTIVE_H2D_BYTES="<<h1-h0<<" ACTIVE_D2H_BYTES="<<d1-d0<<" ZERO_REPEAT_H2D="<<(zero?"PASS":"FAIL")<<'\n';return err<=1e-9&&termerr<=1e-9&&sym&&repeat&&zero;}
static bool run100(){const fs::path f="sync_gpu/tests/fixtures/figure1_reference";auto k=load(f/"knots.txt");GlobalParameters p{load(f/"p_initial_gamma_new.txt"),load(f/"p_initial_global_mu.txt"),load(f/"p_initial_global_sigma.txt"),.25,1.,.11};auto w=worker100(100);auto want=load(f/"p_initial_worker_0_hessian.txt");GpuContext c(0);(void)build_device_mu_sigma_local(c,w,k,p);unsetenv("FEDSPATIAL_MIXED_TRACE_TILED_ACTION");unsetenv("FEDSPATIAL_MIXED_CONTRACTIONS_TILED");auto h0=c.raw_h2d_bytes(),d0=c.result_d2h_bytes();auto a=compute_device_delta_theta_mixed_hessian_reduction_streamed(c,w,k,p);auto h1=c.raw_h2d_bytes(),d1=c.result_d2h_bytes();auto b=compute_device_delta_theta_mixed_hessian_reduction_streamed(c,w,k,p);const auto action0=c.region().mixed_action_tile_calls,rhs0=c.region().mixed_action_tile_rhs_columns,trace0=c.region().mixed_action_trace_tile_calls,bi0=c.region().mixed_bi_w2b_gemm_calls,v0=c.region().mixed_v_tz_tile_calls,vrhs0=c.region().mixed_v_tz_rhs_columns;setenv("FEDSPATIAL_MIXED_TRACE_TILED_ACTION","1",1);setenv("FEDSPATIAL_MIXED_CONTRACTIONS_TILED","1",1);auto tiled=compute_device_delta_theta_mixed_hessian_reduction_streamed(c,w,k,p);unsetenv("FEDSPATIAL_MIXED_TRACE_TILED_ACTION");unsetenv("FEDSPATIAL_MIXED_CONTRACTIONS_TILED");double e=std::max(std::abs(a.mixed[0]-want(0,1)),std::abs(a.mixed[1]-want(0,2))),scale=std::max({1.,std::abs(want(0,1)),std::abs(want(0,2))}),se=symerr(want),st=0.;for(int i=0;i<2;++i){st=std::max(st,std::abs(a.mixed[i]-tiled.mixed[i]));for(int j=0;j<5;++j)st=std::max(st,std::abs(a.terms[i][j]-tiled.terms[i][j]));}bool repeat=std::memcmp(&a,&b,sizeof(a))==0,zero=c.raw_h2d_bytes()==h1,sym=se<=kReferenceSymmetryTolerance,scalar_tile=st<=1e-10;std::cout<<"STREAM_MIXED_HESSIAN_N=100 PYTHON_AUTOGRAD_MAX_ABS="<<e<<" MAX_REL="<<e/scale<<" SCALAR_V_TILED_MAX_ABS="<<st<<" SYMMETRY_MAX_ABS="<<se<<" SYMMETRY="<<(sym?"PASS":"FAIL")<<" EXACT_REPEAT="<<(repeat?"PASS":"FAIL")<<" SCALAR_V_TILED="<<(scalar_tile?"PASS":"FAIL")<<" TILE_ACTION_CALLS="<<c.region().mixed_action_tile_calls-action0<<" TILE_ACTION_RHS="<<c.region().mixed_action_tile_rhs_columns-rhs0<<" TILE_TRACE_CALLS="<<c.region().mixed_action_trace_tile_calls-trace0<<" BI_GEMM_CALLS="<<c.region().mixed_bi_w2b_gemm_calls-bi0<<" V_TZ_TILE_CALLS="<<c.region().mixed_v_tz_tile_calls-v0<<" V_TZ_RHS="<<c.region().mixed_v_tz_rhs_columns-vrhs0<<" ACTIVE_H2D_BYTES="<<h1-h0<<" ACTIVE_D2H_BYTES="<<d1-d0<<" ZERO_REPEAT_H2D="<<(zero?"PASS":"FAIL")<<'\n';return e<=1e-8&&sym&&repeat&&zero&&scalar_tile;}
int main(){try{bool ok=run_small()&&run100();std::cout<<"STREAMED_MIXED_HESSIAN_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
